;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if5_e_go:			ld sp, if5_e
			ret
if6_e_go:			ld sp, if6_e
			ret
do2_t_go:			ld sp, do2_t
			ret
do12_e_go:			ld sp, do12_e
			ret
do12_t_go:			ld sp, do12_t
			ret
if14_e_go:			ld sp, if14_e
			ret

p_waitwrap_c:		; call waitwrap (turbo)
			ld hl, 0
			ld (var_waitwrap_p), hl
			ld hl, 0
			ld (var_waitwrap_q), hl
			ld (p_waitwrap_rs), sp
			ld sp, p_waitwrap
			ret
p_waitwrap_r:		; end of waitwrap
			ld sp, (p_waitwrap_rs)
			ret
p_status_c:		; call status (turbo)
			ld (p_status_rs), sp
			ld sp, p_status
			ret
p_status_r:		; end of status
			ld sp, (p_status_rs)
			ret
p_l2_init_c:		; call init (turbo)
			pop hl			; backcolour
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_l2_init_backcolour), de
			ld (p_l2_init_rs), sp
			ld sp, p_l2_init
			ret
p_l2_init_r:		; end of init
			ld sp, (p_l2_init_rs)
			ret

